  n_positions: number;        // total debt positions across all BDCs
  avg_holders: number;        // mean # of BDC holders per attributed company
  total_fv: number;           // sum of latest-quarter FV across those positions, USD

  // Credit lens — position-count weighted percentages (0-100)
